import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p42_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor maxpool2d_forward_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("maxpool2d_forward_cuda", &maxpool2d_forward_cuda, "Max Pool 2D forward (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void maxpool2d_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int H_out, int W_out,
    int kernel_size, int stride, int padding, int dilation
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = (int64_t)N * C * H_out * W_out;
    if (idx >= total) return;

    int ow = idx % W_out;
    int oh = (idx / W_out) % H_out;
    int c  = (idx / (W_out * H_out)) % C;
    int n  = (idx / (W_out * H_out * C));

    int h_start = oh * stride - padding;
    int w_start = ow * stride - padding;

    float maxval = -FLT_MAX;
    #pragma unroll
    for (int kh = 0; kh < kernel_size; kh++) {
        int ih = h_start + kh * dilation;
        if (ih < 0 || ih >= H) continue;
        #pragma unroll
        for (int kw = 0; kw < kernel_size; kw++) {
            int iw = w_start + kw * dilation;
            if (iw < 0 || iw >= W) continue;
            float val = __ldg(&input[((int64_t)n * C + c) * H * W + (int64_t)ih * W + iw]);
            if (val > maxval) maxval = val;
        }
    }
    output[idx] = maxval;
}

torch::Tensor maxpool2d_forward_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 4, "x must be 4D");

    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);

    // Fixed params: kernel_size=4, stride=1, padding=1, dilation=1
    const int kernel_size = 4;
    const int stride = 1;
    const int padding = 1;
    const int dilation = 1;

    int H_out = (H + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int W_out = (W + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, x.options());

    int64_t total = (int64_t)N * C * H_out * W_out;
    int threads = 256;
    int blocks = (int)((total + threads - 1) / threads);

    maxpool2d_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        H_out, W_out,
        kernel_size, stride, padding, dilation
    );

    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs Max Pooling 2D.
        """
    def __init__(self, kernel_size: int, stride: int, padding: int, dilation: int):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                Initializes the Max Pooling 2D layer.

                Args:
                    kernel_size (int): Size of the pooling window.
                    stride (int): Stride of the pooling window.
                    padding (int): Padding to be applied before pooling.
                    dilation (int): Spacing between kernel elements.
                """
        self.maxpool = nn.MaxPool2d(kernel_size=kernel_size, stride=stride, padding=padding, dilation=dilation)
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Applies Max Pooling 2D to the input tensor.

                Args:
                    x (torch.Tensor): Input tensor of shape (batch_size, channels, height, width).

                Returns:
                    torch.Tensor: Output tensor after Max Pooling 2D, shape (batch_size, channels, pooled_height, pooled_width).
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        ks = self.maxpool.kernel_size
        st = self.maxpool.stride
        pa = self.maxpool.padding
        di = self.maxpool.dilation
        if (x.is_cuda and x.dtype == torch.float32 and x.is_contiguous() and x.dim() == 4
                and ks == 4 and st == 1 and pa == 1 and di == 1):
            return _stark_get_extension().maxpool2d_forward_cuda(x)
        return self.maxpool(x)
        # <<<END_IMPROVE>>>

