# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

// Thread-coarsened kernel: each thread computes 4 adjacent output elements along W.
// Fixed params: kernel_size=4, stride=1, padding=1, dilation=1
// Launch: grid=(ceil(W_out,threads*4), H_out, N*C), block=(threads,1,1)
__global__ void maxpool2d_coarsened_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    int N, int C, int H, int W,
    int H_out, int W_out
) {
    // Each thread handles 4 consecutive output columns
    int base_ow = ((int)blockIdx.x * blockDim.x + (int)threadIdx.x) * 4;
    int oh = blockIdx.y;
    int nc = blockIdx.z;  // flattened n*C + c

    if (oh >= H_out || base_ow >= W_out) return;

    int n = nc / C;
    int c = nc % C;

    // h_start for this output row (stride=1, padding=1)
    int h_start = oh - 1;  // oh * stride - padding

    // Base pointer for this (n,c) channel
    const float* ch_ptr = input + ((int64_t)n * C + c) * (int64_t)H * W;

    // Four accumulators
    float m0 = -FLT_MAX, m1 = -FLT_MAX, m2 = -FLT_MAX, m3 = -FLT_MAX;

    // w_start for each of the 4 outputs: base_ow+lane - 1 (stride=1, padding=1)
    int ws0 = base_ow - 1;
    int ws1 = base_ow;
    int ws2 = base_ow + 1;
    int ws3 = base_ow + 2;

    #pragma unroll
    for (int kh = 0; kh < 4; kh++) {
        int ih = h_start + kh;
        if (ih < 0 || ih >= H) continue;
        const float* row_ptr = ch_ptr + (int64_t)ih * W;

        #pragma unroll
        for (int kw = 0; kw < 4; kw++) {
            // Output 0
            if (base_ow < W_out) {
                int iw0 = ws0 + kw;
                if (iw0 >= 0 && iw0 < W) {
                    float v = __ldg(row_ptr + iw0);
                    if (v > m0) m0 = v;
                }
            }
            // Output 1
            if (base_ow + 1 < W_out) {
                int iw1 = ws1 + kw;
                if (iw1 >= 0 && iw1 < W) {
                    float v = __ldg(row_ptr + iw1);
                    if (v > m1) m1 = v;
                }
            }
            // Output 2
            if (base_ow + 2 < W_out) {
                int iw2 = ws2 + kw;
                if (iw2 >= 0 && iw2 < W) {
                    float v = __ldg(row_ptr + iw2);
                    if (v > m2) m2 = v;
                }
            }
            // Output 3
            if (base_ow + 3 < W_out) {
                int iw3 = ws3 + kw;
                if (iw3 >= 0 && iw3 < W) {
                    float v = __ldg(row_ptr + iw3);
                    if (v > m3) m3 = v;
                }
            }
        }
    }

    // Write outputs
    int64_t out_base = ((int64_t)nc * H_out + oh) * W_out;
    if (base_ow     < W_out) output[out_base + base_ow    ] = m0;
    if (base_ow + 1 < W_out) output[out_base + base_ow + 1] = m1;
    if (base_ow + 2 < W_out) output[out_base + base_ow + 2] = m2;
    if (base_ow + 3 < W_out) output[out_base + base_ow + 3] = m3;
}

