    int grid_x = (W_out + threads * 4 - 1) / (threads * 4);
    int grid_y = H_out;
    int grid_z = N * C;

    dim3 grid(grid_x, grid_y, grid_z);
    dim3 block(threads, 1, 1);

    maxpool2d_coarsened_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        H_out, W_out
    );

    return output;
}
